{
  "name": "Material purchase requests · practice",
  "active": false,
  "nodes": [
    {
      "id": "compras-material-0",
      "name": "Start practice",
      "type": "n8n-nodes-base.manualTrigger",
      "typeVersion": 1,
      "position": [
        0,
        0
      ],
      "parameters": {}
    },
    {
      "id": "compras-material-1",
      "name": "Example data",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        240,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return [{ json: {\"id\":\"COM-01\",\"item\":\"Notebooks\",\"units\":20,\"unitCost\":3,\"budget\":50} }];"
      }
    },
    {
      "id": "compras-material-2",
      "name": "Check the number",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        480,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "const seen = new Set(); return $input.all().map(item => { const x = item.json; if (typeof x.id !== 'string' || !x.id.trim()) throw new Error('Missing id'); const sample = {\"id\":\"COM-01\",\"item\":\"Notebooks\",\"units\":20,\"unitCost\":3,\"budget\":50}; for (const [key,value] of Object.entries(sample)) { if (!(key in x)) throw new Error('Missing field: '+key); if (value !== null && typeof x[key] !== typeof value) throw new Error('Wrong type: '+key); if (typeof value === 'number' && (!Number.isFinite(x[key]) || x[key] < 0)) throw new Error('Invalid number: '+key); } if (seen.has(x.id)) throw new Error('Repeated id in this run'); seen.add(x.id); return item; });"
      }
    },
    {
      "id": "compras-material-3",
      "name": "Material purchase requests",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        720,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return $input.all().map(item => { const x = item.json; return { json: { ...x, result: x.units * x.unitCost > x.budget ? \"review\" : \"ready\" } }; });"
      }
    },
    {
      "id": "compras-material-4",
      "name": "Keep for review",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        960,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return $input.all().map(item => ({ json: { ...item.json, reviewedBy: '', approved: false } }));"
      }
    },
    {
      "id": "compras-material-5",
      "name": "Show the result",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        1200,
        0
      ],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "return $input.all().map(item => ({ json: { ...item.json, practiceOnly: true, savedExternally: false } }));"
      }
    }
  ],
  "connections": {
    "Start practice": {
      "main": [
        [
          {
            "node": "Example data",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Example data": {
      "main": [
        [
          {
            "node": "Check the number",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Check the number": {
      "main": [
        [
          {
            "node": "Material purchase requests",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Material purchase requests": {
      "main": [
        [
          {
            "node": "Keep for review",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Keep for review": {
      "main": [
        [
          {
            "node": "Show the result",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1"
  }
}

